<?php
/**
 * PHPUnit bootstrap: WordPress, a real database, and a plugin's tables.
 *
 * Everything this library does is about what BerlinDB and MySQL actually do
 * -- the order rows come back in, what one statement can promise, whether a
 * table is there -- so the suite runs against both rather than stubs of
 * them. tests/fixtures/acme is a small plugin whose classes and functions
 * were generated by sugarcommerce/schema, the way a real plugin's are.
 *
 * @package SugarCommerce\Data
 */

declare( strict_types=1 );

require_once dirname( __DIR__ ) . '/vendor/autoload.php';

$data_tests_tests_dir = getenv( 'WP_TESTS_DIR' ) ?: dirname( __DIR__ ) . '/vendor/wp-phpunit/wp-phpunit';

if ( ! is_readable( $data_tests_tests_dir . '/includes/functions.php' ) ) {
	fwrite( STDERR, "Could not find the WordPress test library at {$data_tests_tests_dir}. Run 'composer install', or set WP_TESTS_DIR.\n" );
	exit( 1 );
}

require_once $data_tests_tests_dir . '/includes/functions.php';

tests_add_filter(
	'muplugins_loaded',
	static function (): void {
		require_once __DIR__ . '/fixtures/acme/plugin.php';
	}
);

require_once $data_tests_tests_dir . '/includes/bootstrap.php';
